CREATE COLUMN TABLE "TEST_AP"."OBTD" ("BatchNum" INTEGER CS_INT NOT NULL , "Status" NVARCHAR(1) DEFAULT 'O', "NumOfTrans" SMALLINT CS_INT, "DateID" LONGDATE CS_LONGDATE, "LocTotal" DECIMAL(21,6) CS_FIXED, "FcTotal" DECIMAL(21,6) CS_FIXED, "SysTotal" DECIMAL(21,6) CS_FIXED, "MemoID" NVARCHAR(50), "UserSign" SMALLINT CS_INT, "Remarks" NVARCHAR(50), PRIMARY KEY ("BatchNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OBTD_STATUS" ON "TEST_AP"."OBTD" ( "Status" ASC )